(7415114, 1169546, 32108, '<td valign="top">My top pick with a 9. Would have been 10 if:<br/>* car was centred or had space in front<br/>* whites bumped a tad more<br/>* couldn''t see wheels</td>', 'My top pick with a 9. Would have been 10 if:* car was centred or had space in front* whites bumped a tad more* couldn''t see wheels', '2015-11-09 00:31:21.000000', NULL, 1),
(7415115, 1169541, 32108, '<td valign="top">Love the low angle and reflections</td>', 'Love the low angle and reflections', '2015-11-09 00:31:54.000000', NULL, 1),
(7415116, 1169564, 32108, '<td valign="top">8 from me but imho could have been a 10 in better light</td>', '8 from me but imho could have been a 10 in better light', '2015-11-09 00:33:04.000000', NULL, 1),
(7415117, 1169542, 32108, '<td valign="top">bumping to 8 ''cause I really can''t fault it, great light, tones, DOF, angle &amp; subject</td>', 'bumping to 8 ''cause I really can''t fault it, great light, tones, DOF, angle & subject', '2015-11-09 00:34:55.000000', NULL, 1),
(7415118, 1169525, 32108, '<td valign="top">PP is a little harsh for my taste - 7</td>', 'PP is a little harsh for my taste - 7', '2015-11-09 00:35:30.000000', NULL, 1),
(7415119, 1169417, 32108, '<td valign="top">Nice to see a different approach - 7. Would have given more if the view thru the sunroof was better.</td>', 'Nice to see a different approach - 7. Would have given more if the view thru the sunroof was better.', '2015-11-09 00:37:37.000000', NULL, 1),
(7415120, 1169543, 32108, '<td valign="top">Good detail shot with sharp lines - 6</td>', 'Good detail shot with sharp lines - 6', '2015-11-09 00:38:34.000000', NULL, 1),
(7415121, 1169562, 32108, '<td valign="top">good exposure and cool subject - 6. Would have given more if you changed angle to add dimension.</td>', 'good exposure and cool subject - 6. Would have given more if you changed angle to add dimension.', '2015-11-09 00:40:08.000000', NULL, 1),
(7415122, 1169566, 32108, '<td valign="top">Have given 6 because I feel you tried to do something good here by isolating the car and placing the neon sign just so and getting low, but imho the image as a whole is a little flat.</td>', 'Have given 6 because I feel you tried to do something good here by isolating the car and placing the neon sign just so and getting low, but imho the image as a whole is a little flat.', '2015-11-09 00:43:10.000000', NULL, 1),
