(7415125, 1169581, 32108, '<td valign="top">cool subject and great low angle - 6. imho would have been better with a shallower dof and less tiles in the foreground</td>', 'cool subject and great low angle - 6. imho would have been better with a shallower dof and less tiles in the foreground', '2015-11-09 00:46:27.000000', NULL, 1),
