(7415255, 1169586, 114225, '<td valign="top">Needs to be focused.</td>', 'Needs to be focused.', '2015-11-09 14:56:11.000000', NULL, 1),
(7415448, 1169514, 30861, '<td valign="top">Best in show from my perspective. Others may debate this, saying the car''s not the "subject" of the picture, but I can''t agree with that.Everything in the image leads us to the clarity of the bright red car. The palette here is extraordinary, right down to the grace note of the pastel-green Chevy tailgate. It''s my only 10 at this point... Looking at the Texas plates, I''ll take a flyer and say this is a Spiffy picture :-)</td>', 'Best in show from my perspective. Others may debate this, saying the car''s not the "subject" of the picture, but I can''t agree with that.Everything in the image leads us to the clarity of the bright red car. The palette here is extraordinary, right down to the grace note of the pastel-green Chevy tailgate. It''s my only 10 at this point... Looking at the Texas plates, I''ll take a flyer and say this is a Spiffy picture :-)', '2015-11-10 18:50:50.000000', NULL, 1),
